#!/usr/bin/env python3
"""Build the offline Handler context from maintained rules and compiled source."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "context/handler-8k.md"


def render():
    skill = (ROOT / "skills/core-handler.md").read_text()
    rules = skill.split("<!-- packet:start -->\n", 1)[1].split("<!-- packet:end -->", 1)[0]
    source = (ROOT / "example/standard/internal/handler/user.go").read_text()
    return (
        "# Core v3: offline HTTP Handler task context\n\n"
        "Generated by scripts/build-handler-context.py; do not edit.\n"
        "For an 8k window: replace duplicate framework knowledge, not applicable repository instructions.\n"
        "Reserve remaining space for your task, source and answer. Tokenize with your model first.\n"
        "Scope: add/edit a downstream HTTP Handler in an existing Core project.\n"
        "No file tools: ask for missing Service signatures; never invent their APIs.\n\n"
        + rules
        + "\n## Compiled reference: example/standard/internal/handler/user.go\n\n"
        "This file belongs to example/standard; its imports refer to real project packages.\n"
        "It is not a standalone application. Adapt imports and service methods to your project.\n\n```go\n"
        + source
        + "```\n\n## Finish\n\n"
        "Preserve unrelated edits. Test routes, invalid input, not-found and internal-error status.\n"
        "Run gofmt on changed Go files, relevant tests, and git diff --check.\n"
        "Report executed checks and remaining gaps. Follow repository review requirements; Core changes require an independent reviewer and re-review after fixes. Do not commit/publish unless requested.\n"
        "For new projects, lifecycle, auth or database work, request the matching reference/source.\n"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail on generated drift or size overflow")
    args = parser.parse_args()
    content = render()
    # shortcut: UTF-8 bytes bound size, not model tokens; use the target tokenizer before inference.
    size = len(content.encode("utf-8"))
    if size > 6000:
        parser.exit(1, f"Handler context exceeds 6000-byte maintenance budget: {size}\n")
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            parser.exit(1, "Handler context is stale; run python3 scripts/build-handler-context.py\n")
    else:
        OUTPUT.write_text(content)
    print(f"Handler context: {size} UTF-8 bytes; {'checked' if args.check else 'generated'}")


if __name__ == "__main__":
    main()
